@Iteration.iteration_protocol_iter
     : forall (E MN : Type -> Type) (I A : Type) (step : I -> PTreeDefinition.ptree E MN (I + A))
         (i : I),
       @PStruct.pstruct E MN A A (@eq A)
         (@PTreeDefinition.PTree.interp (Iteration.iterationE I A) E MN
            (@Iteration.iteration_handler I A E MN step) A (@Iteration.iteration_protocol I A MN i))
         {|
           PTreeDefinition._observe :=
             @PTreeDefinition.TauF E MN A (PTreeDefinition.ptree E MN A)
               (@PTreeDefinition.PTree.iter E MN A I step i)
         |}

@Iteration.iteration_machine_related
     : forall (E MN MF : Type -> Type) (FI : Measure.SemanticMeasure MF)
         (FC : @Measure.SemanticMeasureCoreLaws MF FI),
       @Measure.SemanticMeasureBindLaws MF FI ->
       forall (MX : Mixed.MixedMeasure MN MF) (FO : @Omega.SemanticOmega MF FI),
       @Omega.SemanticMeasureOrderLaws MF FI FO ->
       @Omega.SemanticOmegaLaws MF FI FO ->
       @Omega.SemanticOmegaCofinalityLaws MF FI FO ->
       @Omega.SemanticMeasureDiagonalLaws MF FI FO ->
       @Omega.SemanticOmegaFubiniLaws MF FI FO ->
       @BindOrder.SemanticMeasureBindOrderLaws MF FI FO ->
       @BindOrder.MixedMeasureBindOrderLaws MN MF FI MX FO ->
       @Omega.SemanticOmegaDirectedCofinalityLaws MF FI FO ->
       @Omega.SemanticOmegaSelection MF FI FO ->
       @RelationalClosure.relational_zero MF FI FO ->
       @RelationalClosure.relational_lub MF FI FO ->
       forall (I1 I2 A B : Type) (step1 : I1 -> PTreeDefinition.ptree E MN (I1 + A))
         (step2 : I2 -> PTreeDefinition.ptree E MN (I2 + B)) (SI : I1 -> I2 -> Prop)
         (RR : A -> B -> Prop),
       (forall (i : I1) (j : I2),
        SI i j ->
        @PEutt.peutt E MN MF FI FC MX FO (I1 + A) (I2 + B)
          (@PStruct.pstruct_iter_sum_rel I1 I2 A B SI RR) (step1 i) (step2 j)) ->
       forall (c : @HandlerMachine.handler_config (Iteration.iterationE I1 A) E MN A)
         (d : @HandlerMachine.handler_config (Iteration.iterationE I2 B) E MN B),
       @Iteration.iteration_configs E MN MF FI FC MX FO I1 I2 A B SI RR c d ->
       @PEutt.peutt E MN MF FI FC MX FO A B RR
         (@HandlerMachine.handler_config_tree (Iteration.iterationE I1 A) E MN
            (@Iteration.iteration_handler I1 A E MN step1) A c)
         (@HandlerMachine.handler_config_tree (Iteration.iterationE I2 B) E MN
            (@Iteration.iteration_handler I2 B E MN step2) B d)

